import functools
import typing
import unittest
from abc import ABC


class LateVirtualRegistration(unittest.TestCase):
    """Regressions for late virtual subclass registration with union
    dispatchers."""

    def test_pep604_union_late_virtual_registration(self):
        """PEP 604 union (A | B) with late virtual subclass registration."""

        class PluginBase(ABC):
            pass

        class Payload:
            pass

        @functools.singledispatch
        def handler(x):
            return "default"

        @handler.register(PluginBase | int)
        def union_handler(x):
            return "union"

        p = Payload()
        # Before virtual registration, Payload dispatches to the default.
        self.assertEqual(handler(p), "default")
        # int member still dispatches to the union handler.
        self.assertEqual(handler(1), "union")

        # Late virtual registration: Payload becomes a virtual subclass
        # of PluginBase.  No manual cache-clear is called.
        PluginBase.register(Payload)

        # The same Payload instance must now reach the union handler.
        self.assertEqual(handler(p), "union")
        # int still works.
        self.assertEqual(handler(1), "union")

    def test_typing_union_late_virtual_registration(self):
        """typing.Union[A, B] with late virtual subclass registration."""

        class PluginBase(ABC):
            pass

        class Payload:
            pass

        @functools.singledispatch
        def handler(x):
            return "default"

        @handler.register(typing.Union[PluginBase, int])
        def union_handler(x):
            return "union"

        p = Payload()
        self.assertEqual(handler(p), "default")
        self.assertEqual(handler(1), "union")

        PluginBase.register(Payload)

        self.assertEqual(handler(p), "union")
        self.assertEqual(handler(1), "union")


class OverlappingVirtualMembership(unittest.TestCase):
    def exercise(self, style, related=False, explicit=False):
        class Left(ABC):
            pass
        class Right(Left if related else ABC):
            pass
        class Value:
            pass
        @functools.singledispatch
        def route(value):
            return 'default'
        union = Left | Right if style == 'pipe' else typing.Union[Left, Right]
        def shared(value):
            return 'shared'
        route.register(union, shared)
        value = Value()
        self.assertEqual(route(value), 'default')
        Left.register(Value)
        self.assertEqual(route(value), 'shared')
        Right.register(Value)
        if related:
            self.assertIs(route.dispatch(Value), shared)
            self.assertEqual(route(value), 'shared')
        else:
            with self.assertRaises(RuntimeError) as caught:
                route(value)
            self.assertIs(type(caught.exception), RuntimeError)
            self.assertEqual(str(caught.exception),
                f'Ambiguous dispatch: {Left} or {Right}')
        if explicit:
            def specific(value):
                return 'specific'
            self.assertIs(route.register(Value, specific), specific)
            self.assertIs(route.dispatch(Value), specific)
            self.assertEqual(route(value), 'specific')

    def test_unrelated_members(self):
        for style in ('pipe', 'typing'):
            with self.subTest(style=style):
                self.exercise(style)

    def test_related_members(self):
        for style in ('pipe', 'typing'):
            with self.subTest(style=style):
                self.exercise(style, related=True)

    def test_concrete_registration(self):
        for style in ('pipe', 'typing'):
            with self.subTest(style=style):
                self.exercise(style, explicit=True)


if __name__ == "__main__":
    unittest.main()
